import { afterEach, beforeEach, describe, expect, mock, setSystemTime, test } from "bun:test";
import type { RecentArticle } from "../../../../../../apps/mobile/src/modules/recents/lib/history";
import { FAVICON_PROXY_VERSION } from "@kyomi/worker/favicon/browser";
import type { ArticleListItemDto, ReadingProgressDto } from "@kyomi/reader/schemas/article";

// lib/auth builds the expo-secure-store backed auth client at import time, so only it is stubbed.
// The real resolveMobileApiUrl in lib/api still resolves the favicon proxy path.
mock.module("../../../../../../apps/mobile/src/lib/auth", () => ({
  getAuthCookie: () => "",
  resolveAuthOrigin: () => "https://api.kyomi.test",
}));

const { faviconUrls, toArticleRow } =
  await import("../../../../../../apps/mobile/src/modules/articles/lib/list-rows");
const { toRecentRow } = await import("../../../../../../apps/mobile/src/modules/recents/lib/rows");

const NOW = Date.parse("2026-08-05T12:00:00.000Z");
const PROXY_FAVICON = `https://api.kyomi.test/api/favicon?domain=${encodeURIComponent("https://example.com")}&v=${FAVICON_PROXY_VERSION}`;
const DEFAULT_FAVICONS = [PROXY_FAVICON, "https://example.com/favicon.ico"];
const hoursAgo = (hours: number) => new Date(NOW - hours * 60 * 60 * 1000).toISOString();

const progress = (overrides: Partial<ReadingProgressDto> = {}): ReadingProgressDto => ({
  completedAt: null,
  engaged: true,
  lastReadAt: hoursAgo(1),
  maxProgress: 0.4,
  progress: 0.4,
  remainingMinutes: 6,
  state: "reading",
  ...overrides,
});

const item = (overrides: Partial<ArticleListItemDto> = {}): ArticleListItemDto => ({
  articleType: "feed",
  categories: [],
  feedFaviconUrl: null,
  feedId: "feed-id",
  feedSiteUrl: "https://example.com",
  feedTitle: "Example",
  feedUrl: "https://example.com/feed.xml",
  id: "article-1",
  isRead: false,
  isSaved: false,
  lastViewedAt: null,
  link: "https://www.example.com/posts/1",
  publishedAt: hoursAgo(2),
  readingProgress: null,
  summary: "A short summary.",
  title: "Article 1",
  ...overrides,
});

const recent = (overrides: Partial<RecentArticle> = {}): RecentArticle => ({
  feedFaviconUrl: null,
  feedSiteUrl: "https://example.com",
  feedTitle: "Example",
  feedUrl: "https://example.com/feed.xml",
  id: "recent-1",
  link: "https://www.example.com/posts/1",
  title: "Article 1",
  viewedAt: hoursAgo(3),
  ...overrides,
});

beforeEach(() => {
  setSystemTime(new Date(NOW));
});

afterEach(() => {
  setSystemTime();
});

describe("faviconUrls", () => {
  test("resolves the /api/ proxy candidate against the API origin and leaves direct URLs alone", () => {
    const urls = faviconUrls(item({ feedFaviconUrl: "https://cdn.example.com/icon.png" }));

    const proxy = new URL(urls[0] ?? "");
    expect(proxy.origin).toBe("https://api.kyomi.test");
    expect(proxy.pathname).toBe("/api/favicon");
    expect(proxy.searchParams.get("domain")).toBe("https://example.com");
    expect(urls.slice(1)).toEqual([
      "https://cdn.example.com/icon.png",
      "https://example.com/favicon.ico",
    ]);
  });

  test("falls back to the article link when the feed has no feed or site URL", () => {
    const urls = faviconUrls(
      item({ feedSiteUrl: null, feedUrl: null, link: "https://blog.example.org/post/1" }),
    );

    expect(new URL(urls[0] ?? "").searchParams.get("domain")).toBe("https://blog.example.org");
    expect(urls.at(-1)).toBe("https://blog.example.org/favicon.ico");
  });

  test("offers no candidates when no usable origin exists", () => {
    expect(faviconUrls(item({ feedSiteUrl: null, feedUrl: null, link: "not a url" }))).toEqual([]);
  });
});

describe("toArticleRow", () => {
  test("maps an article to a continuing, saved-aware row with its source and time labels", () => {
    const row = toArticleRow(
      item({
        isSaved: true,
        lastViewedAt: hoursAgo(1),
        readingProgress: progress(),
        summary: "A short summary.",
      }),
    );

    expect(row).toEqual({
      continueLabel: "Continue reading · 6 min left",
      faviconUrls: DEFAULT_FAVICONS,
      feedTitle: "Example",
      id: "article-1",
      isContinuing: true,
      isSaved: true,
      kind: "article",
      sourceLabel: "example.com",
      summary: "A short summary.",
      timeLabel: "2h",
      title: "Article 1",
    });
  });

  test("opening an article is not enough to continue it", () => {
    const opened = toArticleRow(item({ lastViewedAt: hoursAgo(5) }));

    expect(opened.isContinuing).toBe(false);
    expect(opened.continueLabel).toBeUndefined();
  });

  test("continues only engaged articles that are still being read or resurfaced", () => {
    const continuing = (overrides: Partial<ReadingProgressDto>) =>
      toArticleRow(item({ readingProgress: progress(overrides) })).isContinuing;

    expect(continuing({})).toBe(true);
    expect(continuing({ state: "resurfacing" })).toBe(true);
    expect(continuing({ engaged: false })).toBe(false);
    expect(continuing({ state: "completed" })).toBe(false);
    expect(continuing({ state: "dismissed" })).toBe(false);
    expect(continuing({ state: "abandoned" })).toBe(false);
  });

  test("labels a continuing row with the time left, and with no time when it is unknown", () => {
    const label = (overrides: Partial<ReadingProgressDto>) =>
      toArticleRow(item({ readingProgress: progress(overrides) })).continueLabel;

    expect(label({ remainingMinutes: 12 })).toBe("Continue reading · 12 min left");
    expect(label({ remainingMinutes: 0 })).toBe("Continue reading · Under 1 min left");
    expect(label({ remainingMinutes: null })).toBe("Continue reading");
  });

  test("defaults a missing summary to an empty string", () => {
    expect(toArticleRow(item({ summary: null })).summary).toBe("");
  });

  test("reuses the row for the same item object and rebuilds it for a changed copy", () => {
    const original = item();
    const first = toArticleRow(original);

    expect(toArticleRow(original)).toBe(first);

    const saved = { ...original, isSaved: true };
    const rebuilt = toArticleRow(saved);
    expect(rebuilt).not.toBe(first);
    expect(rebuilt.isSaved).toBe(true);
    expect(toArticleRow(original).isSaved).toBe(false);
  });
});

describe("toRecentRow", () => {
  test("builds a plain history row with a Viewed time label", () => {
    expect(toRecentRow(recent())).toEqual({
      faviconUrls: DEFAULT_FAVICONS,
      feedTitle: "Example",
      id: "recent-1",
      kind: "recent",
      sourceLabel: "example.com",
      timeLabel: "Viewed 3h",
      title: "Article 1",
    });
  });

  test("reuses the row for the same history entry and rebuilds it for a new object", () => {
    const entry = recent();
    const first = toRecentRow(entry);

    expect(toRecentRow(entry)).toBe(first);
    expect(toRecentRow({ ...entry, viewedAt: hoursAgo(26) }).timeLabel).toBe("Viewed 1d");
  });
});
